<body>

<!-- Header -->
<header class="header">
  <a href="index.html" class="logo">StreamWave</a>
</header>

<!-- Login Form -->
<main class="main">
  <div class="login-box">
    <h1>Enter your info to sign in</h1>
    <p class="subtext">Or <a href="index.html">get started with a new account</a>.</p>
    <form id="loginForm" onsubmit="return false;">
      <div class="form-group">
        <input type="text" placeholder="Email address or mobile number" aria-label="Email address or mobile number" required autocomplete="username">
      </div>
      <div class="form-group">
        <input type="password" placeholder="Password" aria-label="Password" required autocomplete="current-password">
      </div>
      <button type="submit" class="btn-continue">Continue</button>
    </form>

    <div class="help-toggle">
      <button class="help-btn" onclick="toggleHelp()" aria-expanded="false" id="helpBtn">Get help</button>
      <div class="help-content" id="helpContent" role="region">
        <p>If you're having trouble signing in, try resetting your password or <a href="#">contact our support team</a> for assistance. You can also check the <a href="#">Help Centre</a> for common sign-in issues.</p>
      </div>
